"""Build the unavailable Rust reference registry and browser evidence from reviewed specifications.

This generator never creates trades, fills or performance claims. Run from repository root.
"""
import json
from pathlib import Path
root=Path.cwd();folder=root/'library/joe-ross';data=json.loads((folder/'core-specifications.json').read_text())
q=lambda s:json.dumps(s,ensure_ascii=False)
lines=['//! Generated by library/joe-ross/scripts/generate_registry.py. Source methods, not invented backtests.',
 'use crate::connors::{Ctx, ParamDef, Params, Status, StrategyDef, Trade};',
 'pub fn catalogue() -> Vec<StrategyDef> { vec![']
match=[];evidence={}
for m in data['methods']:
 for direction in m['directions']:
  sid=m['key']+('_l' if direction=='Long' else '_s')
  notes=f"Source: {m['source']['path']}; {m['pages']}. GPT source assessment: {m['conclusion']} Complete contract-level backtest and independent trade audit are not available."
  lines.append('StrategyDef { '+f'id: {q(sid)}, name: {q(m["name"]+" · "+direction)}, group: {q(m["group"]+" · Source reference")}, session: 0, dir: {q(direction)}, status: Status::NotTestable({q(m["reason"])}), needs_volume: false, needs_vix: false, needs_series: &[], book: {q(m["book"])}, rules: &['+','.join(q(s) for s in m['rules'])+f'], notes: {q(notes)}, claim: None '+'},')
  match.append(f'{q(sid)} => Some(({q(m["key"])},{q(m["name"])},{q(direction)})),')
  evidence[sid]={'source':m['source'],'pages':m['pages'],'conclusion':m['conclusion'],'reason':m['reason'],'external':m['external'],'verified_performance':False,'missing_data':m.get('missing_data',[]),'rule_gaps':m.get('rule_gaps',[]),'source_gaps':m.get('source_gaps',[])}
lines+=['] }','pub fn family_of(id: &str) -> Option<(&\'static str, &\'static str, &\'static str)> { match id {',*match,'_ => None } }',
 'pub fn params(_id: &str) -> Option<Vec<ParamDef>> { None }',
 '// An unavailable source reference must never manufacture an empty or simulated successful run.',
 'pub fn run(_id: &str, _x: &Ctx, _from: usize, _to: usize, _p: &Params) -> Option<Vec<Trade>> { None }']
(root/'Context/guru/backend/src/books/joe_ross.rs').write_text('\n'.join(lines)+'\n')
public={'review_date':data['review_date'],'scope':data['scope'],'methods':evidence,'books':data['books'],'finding':'The Manual prints 96.5% for two standard deviations; normal coverage is approximately 95.45%, without guaranteed market-band coverage. The printed CCI divisor is 1.5 versus standard 0.015; the source conflict is explicit and no CCI backtest is enabled.'}
(root/'Context/guru/frontend/joe-ross-evidence.js').write_text('/* Generated reviewed evidence. No prices or performance results. */\nwindow.JoeRossEvidence = '+json.dumps(public,ensure_ascii=False,indent=2)+';\n')
print(f'Generated {len(evidence)} unavailable directional references and page-cited evidence.')
